def transform(grid):
    h, w = len(grid), len(grid[0])

    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            upper, lower = grid[:r], grid[r + 1:]
            n = min(len(upper), len(lower))

            # The overlapping color is the upper panel's non-background
            # color and the lower panel's background color.
            def common_color(panel):
                counts = {}
                for line in panel:
                    for value in line:
                        counts[value] = counts.get(value, 0) + 1
                return max(counts, key=counts.get)

            upper_bg = common_color(upper)
            lower_bg = common_color(lower)
            overlap = next((v for v in set(sum(upper, []))
                            if v != upper_bg and v == lower_bg), lower_bg)

            return [
                [3 if upper[i][j] == overlap and lower[i][j] == overlap
                 else overlap for j in range(w)]
                for i in range(n)
            ]

    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            left = [line[:c] for line in grid]
            right = [line[c + 1:] for line in grid]
            def common_color(panel):
                counts = {}
                for line in panel:
                    for value in line:
                        counts[value] = counts.get(value, 0) + 1
                return max(counts, key=counts.get)

            bg_left, bg_right = common_color(left), common_color(right)
            overlap = next((v for v in set(sum(left, []))
                            if v != bg_left and v == bg_right), bg_right)
            n = min(c, w - c - 1)
            return [
                [3 if left[i][j] == overlap and right[i][j] == overlap
                 else overlap for j in range(n)]
                for i in range(h)
            ]
    return grid
